package com.mushafi.app;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import org.json.*;import java.util.*;
/** Foreground-only device location. No service, background permission or geocoder. */
public final class AutomaticLocation {
 private final Context context;private final Runnable changed;private final LocationManager manager;private LocationListener listener;private BroadcastReceiver receiver;private boolean foreground,precise;private String error="";
 public AutomaticLocation(Context c,Runnable changed){context=c;this.changed=changed;manager=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);}
 public static boolean permission(Context c){return c.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED||c.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 public static PrayerSettings overlay(Context c,PrayerSettings settings){try{String text=c.getSharedPreferences("automatic_location",0).getString("fix","");if(text.isEmpty())return settings;JSONObject fix=new JSONObject(text);for(String key:new String[]{"latitude","longitude","timezone"})settings.json.put(key,fix.get(key));settings.json.put("city","موقعي الحالي").put("confirmed",true);return new PrayerSettings(settings.json);}catch(Exception e){return settings;}}
 public JSONObject status(){JSONObject out=new JSONObject();try{String text=context.getSharedPreferences("automatic_location",0).getString("fix","");out.put("permission",permission(context)).put("foreground",foreground).put("listening",listener!=null).put("hasFix",!text.isEmpty()).put("error",error);boolean providers=false;for(String p:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER})try{providers|=manager.isProviderEnabled(p);}catch(Exception ignored){}out.put("providers",providers);if(!text.isEmpty()){JSONObject fix=new JSONObject(text);out.put("fixedAt",fix.optLong("fixedAt")).put("accuracy",fix.optDouble("accuracy"));}}catch(Exception ignored){}return out;}
 public void start(){foreground=true;if(receiver==null){receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){stopListeners();refreshZone();listen();}};IntentFilter f=new IntentFilter(LocationManager.PROVIDERS_CHANGED_ACTION);f.addAction(Intent.ACTION_TIMEZONE_CHANGED);if(Build.VERSION.SDK_INT>=33)context.registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else context.registerReceiver(receiver,f);}refreshZone();listen();}
 private void listen(){if(!foreground||listener!=null)return;if(manager==null){error="لا تتوفر خدمة الموقع في هذا الجهاز.";changed.run();return;}if(!permission(context)){error="إذن الموقع غير مفعّل؛ نستخدم آخر موقع محفوظ إن وُجد.";changed.run();return;}error="";
  Location best=null;for(String provider:manager.getProviders(true))try{Location l=manager.getLastKnownLocation(provider);if(fresh(l)&&(best==null||l.getAccuracy()<best.getAccuracy()))best=l;}catch(Exception ignored){}if(best!=null)accept(best);
  listener=new LocationListener(){public void onLocationChanged(Location l){if(foreground&&listener==this)accept(l);}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){error="خدمة الموقع متوقفة؛ نستخدم آخر موقع محفوظ.";changed.run();}};boolean listening=false;
  for(String provider:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER})try{if(manager.isProviderEnabled(provider)){manager.requestLocationUpdates(provider,precise?10000:60000,precise?25:1000,listener,Looper.getMainLooper());listening=true;}}catch(Exception ignored){}if(!listening){stopListeners();error="خدمة الموقع متوقفة؛ نستخدم آخر موقع محفوظ إن وُجد.";}changed.run();
 }
 public static boolean fresh(Location l){if(l==null||!l.hasAccuracy()||(Float.isNaN(l.getAccuracy())||Float.isInfinite(l.getAccuracy()))||l.getAccuracy()<=0||l.getAccuracy()>10000||(Double.isNaN(l.getLatitude())||Double.isInfinite(l.getLatitude()))||Math.abs(l.getLatitude())>89||(Double.isNaN(l.getLongitude())||Double.isInfinite(l.getLongitude()))||Math.abs(l.getLongitude())>180)return false;long age=l.getElapsedRealtimeNanos()>0?(SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos())/1000000:System.currentTimeMillis()-l.getTime();return age>=-1000&&age<=120000;}
 public void accept(Location l){if(!foreground||!permission(context)||!fresh(l))return;try{String zone=TimeZone.getDefault().getID();android.content.SharedPreferences prefs=context.getSharedPreferences("automatic_location",0);String previous=prefs.getString("fix","");JSONObject old=previous.isEmpty()?null:new JSONObject(previous);long observed=l.getElapsedRealtimeNanos();if(old!=null&&observed>0&&old.optLong("observedElapsed")>0&&old.optLong("observedElapsed")<=SystemClock.elapsedRealtimeNanos()&&observed<old.optLong("observedElapsed"))return;boolean moved=old==null;if(old!=null){float[] distance=new float[1];Location.distanceBetween(old.getDouble("latitude"),old.getDouble("longitude"),l.getLatitude(),l.getLongitude(),distance);moved=distance[0]>=(precise?Math.max(25,Math.min(100,Math.max(old.optDouble("accuracy",0),l.getAccuracy()))):Math.max(1000,Math.min(5000,Math.max(old.optDouble("accuracy",0),l.getAccuracy()))))||l.getAccuracy()<old.optDouble("accuracy",l.getAccuracy())*.5;}
  JSONObject fix=new JSONObject().put("latitude",l.getLatitude()).put("longitude",l.getLongitude()).put("accuracy",l.getAccuracy()).put("timezone",zone).put("fixedAt",System.currentTimeMillis()).put("observedElapsed",observed);
  // Retain a stable prayer coordinate until meaningful movement; refresh age/accuracy.
  if(old!=null&&!moved){fix.put("latitude",old.getDouble("latitude")).put("longitude",old.getDouble("longitude"));}
  boolean zoneChanged=old!=null&&!zone.equals(old.optString("timezone"));prefs.edit().putString("fix",fix.toString()).apply();PrayerSettings before=PrayerSettings.load(context);PrayerSettings next=overlay(context,new PrayerSettings(before.json));boolean mismatch=Math.abs(before.json.optDouble("latitude")-next.json.optDouble("latitude"))>.00001||Math.abs(before.json.optDouble("longitude")-next.json.optDouble("longitude"))>.00001||!before.json.optString("timezone").equals(zone)||!before.json.optBoolean("confirmed");
  if(moved||zoneChanged||mismatch){next.save(context);PrayerScheduler.schedule(context);}error="";changed.run();
 }catch(Exception e){error="تعذر تحديث الموقع؛ نستخدم آخر موقع محفوظ.";changed.run();}}
 private void refreshZone(){try{android.content.SharedPreferences prefs=context.getSharedPreferences("automatic_location",0);String text=prefs.getString("fix","");if(text.isEmpty())return;JSONObject fix=new JSONObject(text);String zone=TimeZone.getDefault().getID();if(zone.equals(fix.optString("timezone")))return;fix.put("timezone",zone);prefs.edit().putString("fix",fix.toString()).apply();overlay(context,PrayerSettings.load(context)).save(context);PrayerScheduler.schedule(context);changed.run();}catch(Exception ignored){}}
 private void stopListeners(){if(listener!=null){try{manager.removeUpdates(listener);}catch(Exception ignored){}listener=null;}}
 public void setPrecise(boolean value){value=value&&context.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;if(precise==value)return;precise=value;stopListeners();listen();}
 public void stop(){foreground=false;stopListeners();if(receiver!=null){try{context.unregisterReceiver(receiver);}catch(Exception ignored){}receiver=null;}}
}
